import React from "react";
import { useCurrentFrame, useVideoConfig, spring, interpolate, Audio, staticFile, AbsoluteFill } from "remotion";
import { loadFont } from "@remotion/google-fonts/Roboto";
import { loadFont as loadMonoFont } from "@remotion/google-fonts/RobotoMono";

const { fontFamily } = loadFont("normal", { weights: ["300"] });
const { fontFamily: monoFamily } = loadMonoFont("normal", { weights: ["400"] });

// ─── WORD-BY-WORD TEXT ────────────────────────────────────────────────────────
// Words slide up + fade in with a stagger. Block opacity controlled externally
// so the exit can overlap cleanly with the triangle scaling in.

const WordReveal: React.FC<{
  text: string;
  startFrame: number;
  exitFrame?: number;
  exitMode?: "drop" | "shrink";
  wordDelay?: number;
  style?: React.CSSProperties;
}> = ({ text, startFrame, exitFrame, exitMode = "drop", wordDelay = 6, style }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const words = text.split(" ");

  return (
    <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "center", gap: "0.3em", ...style }}>
      {words.map((word, i) => {
        // Entrance: slide up
        const inLocal = Math.max(0, frame - (startFrame + i * wordDelay));
        const inSp = spring({ frame: inLocal, fps, config: { stiffness: 160, damping: 20 } });

        let opacity = inSp;
        let ty = interpolate(inSp, [0, 1], [16, 0]);
        let scale = 1;

        if (exitFrame != null && frame >= exitFrame + i * 2) {
          const exitLocal = frame - (exitFrame + i * 2);
          const t = Math.min(1, exitLocal / 12);
          if (exitMode === "shrink") {
            // Shrink into center — looks like triangle grows from same spot
            const t2 = t * t;
            scale = Math.max(0, 1 - t2 * 2);
            opacity = Math.max(0, 1 - t * 2);
            ty = 0;
          } else {
            // Drop with gravity
            const t2 = t * t;
            opacity = Math.max(0, 1 - t * 2);
            ty = t2 * 220;
          }
        }

        return (
          <span key={i} style={{
            display: "inline-block",
            opacity,
            transform: `translateY(${ty}px) scale(${scale})`,
          }}>
            {word}
          </span>
        );
      })}
    </div>
  );
};

